export const CARDS: Card[] = [
  // ---- standard ----
  { id: "standard-recovery", name: "Recovery", pack: "standard", kind: "individual", multiWinner: false, challenge: "Escape trouble onto short grass", howToWin: "After a wayward shot into trees, deep rough, or sand, get your very next shot to finish on short-mowed grass (fairway, fringe, or green). One clean recovery wins it.", image: require('../../assets/cards/illustrations/standard/recovery.png') },
  { id: "standard-skip-the-beach", name: "Skip the Beach", pack: "standard", kind: "individual", multiWinner: false, challenge: "Stay out of the sand", howToWin: "Keep your ball out any sand traps this hole. If there are no traps, then consider this a freebie.", image: require('../../assets/cards/illustrations/standard/skip-the-beach.png') },
  { id: "standard-split-the-fairway", name: "Split the Fairway", pack: "standard", kind: "individual", multiWinner: false, challenge: "Hit the fairway off the tee", howToWin: "Your first shot off the tee must stop on the fairway, the fringe around the green, or the green itself.", image: require('../../assets/cards/illustrations/standard/split-the-fairway.png') },
  { id: "standard-stay-dry", name: "Stay Dry", pack: "standard", kind: "individual", multiWinner: false, challenge: "No water on this hole", howToWin: "Keep your ball out of the water this hole. If there’s no water, consider this a freebie.", image: require('../../assets/cards/illustrations/standard/stay-dry.png') },
  { id: "standard-tree-free", name: "Tree Free", pack: "standard", kind: "individual", multiWinner: false, challenge: "Stay out of the trees", howToWin: "Keep your ball out of the trees this hole. If there’s no trees, consider this a freebie.", image: require('../../assets/cards/illustrations/standard/tree-free.png') },
  { id: "standard-no-duffs", name: "No Duffs", pack: "standard", kind: "individual", multiWinner: false, challenge: "No divots or chunks with an iron", howToWin: "Play the hole without a single chunk (hitting the ground behind the ball) or blade (catching it thin so it screams across the green) on any chip or pitch. The group judges anything ugly.", image: require('../../assets/cards/illustrations/standard/no-duffs.png') },
  { id: "standard-twenty-feet", name: "Twenty Feet", pack: "standard", kind: "individual", multiWinner: false, challenge: "Approach finishes within 20 feet of the pin", howToWin: "Your approach shot must stop within 20 feet of the hole (about seven paces). On or just off the green both count; pace it off or let the group judge if it's close.", image: require('../../assets/cards/illustrations/standard/twenty-feet.png') },
  { id: "standard-greenside-touch", name: "Greenside Touch", pack: "standard", kind: "individual", multiWinner: false, challenge: "A chip or pitch stops within 6 feet", howToWin: "Hit one chip or pitch from around the green that finishes within 6 feet of the hole (about two and a half paces). Cozy up one short shot to win the card.", image: require('../../assets/cards/illustrations/standard/greenside-touch.png') },
  { id: "standard-lag-from-the-fringe", name: "Lag from the Fringe", pack: "standard", kind: "individual", multiWinner: false, challenge: "From the fringe, get within 3 feet", howToWin: "When you putt or chip from the fringe (the collar around the green), leave it within 3 feet of the hole or hole it out. Judge the speed off the longer grass to win.", image: require('../../assets/cards/illustrations/standard/lag-from-the-fringe.png') },
  { id: "standard-cap-the-damage", name: "Cap the Damage", pack: "standard", kind: "individual", multiWinner: false, challenge: "No double bogey or worse", howToWin: "Finish the hole no more than two strokes over par (two over is called a double bogey). Example: on a par 4, a score of 6 or better wins the card; a 7 or higher loses it.", image: require('../../assets/cards/illustrations/standard/cap-the-damage.png') },
  { id: "standard-five-or-better", name: "Five or Better", pack: "standard", kind: "individual", multiWinner: false, challenge: "Score 5 or better", howToWin: "Get your ball in the hole in 5 total strokes or fewer — counting every swing and any penalty strokes — no matter what the hole's par is.", image: require('../../assets/cards/illustrations/standard/five-or-better.png') },
  { id: "standard-bogey-train", name: "Bogey Train", pack: "standard", kind: "individual", multiWinner: false, challenge: "Bogey or better", howToWin: "Finish the hole no more than one stroke over par (par is the target score printed on the scorecard — one over is called a bogey). Example: on a par 4, a score of 5 or better wins the card; a 6 loses it.", image: require('../../assets/cards/illustrations/standard/bogey-train.png') },
  { id: "standard-close-to-par", name: "Close to Par", pack: "standard", kind: "individual", multiWinner: false, challenge: "Score within one stroke of par", howToWin: "Finish within one stroke of par in either direction. Example: on a par 4, a score of 3, 4, or 5 wins the card; anything else loses it.", image: require('../../assets/cards/illustrations/standard/close-to-par.png') },
  { id: "standard-inside-the-leather-lite", name: "Inside the Leather Lite", pack: "standard", kind: "individual", multiWinner: false, challenge: "Approach finishes within 30 feet of the pin", howToWin: "Your approach shot — the shot where you're trying to reach the green — must stop within 30 feet of the flag (about 10 big paces). Pace it off or let the group judge if it's close.", image: require('../../assets/cards/illustrations/standard/inside-the-leather-lite.png') },
  { id: "standard-fringe-and-better", name: "Fringe & Better", pack: "standard", kind: "individual", multiWinner: false, challenge: "Green or fringe in regulation", howToWin: "Get your ball to stop on the green or the fringe (the collar of short grass around it) fast enough that you still have two shots left to make par — that means within 1 shot on a par 3, 2 shots on a par 4, or 3 shots on a par 5.", image: require('../../assets/cards/illustrations/standard/fringe-and-better.png') },
  { id: "standard-always-fairways", name: "Always Fairways", pack: "standard", kind: "individual", multiWinner: false, challenge: "Only fairways shots to the green", howToWin: "Every shot you take from the teebox to the green is from the fairway or fringe. No bunkers, rough, trees. None of the thick stuff!" },
  { id: "standard-escape-artist", name: "Escape Artist", pack: "standard", kind: "individual", multiWinner: false, challenge: "Never take two shots within a 10ft circle", howToWin: "From every swing, you can never have 2 shots within the same 10 foot circle.  This means if your putt is less than 10 feet from the hole, then you must one putt it.", image: require('../../assets/cards/illustrations/standard/escape-artist.png') },
  { id: "standard-never-short", name: "Never Short", pack: "standard", kind: "individual", multiWinner: false, challenge: "No putt left short all hole", howToWin: "Every putt you hit all hole must reach the hole — going in, stopping next to it, or rolling past all count. Leave even one putt short of the hole and the card is lost.", image: require('../../assets/cards/illustrations/standard/never-short.png') },
  { id: "standard-from-distance", name: "From Distance", pack: "standard", kind: "individual", multiWinner: false, challenge: "Make a putt of 10+ feet", howToWin: "Sink a putt from 10 feet or longer (about three or four paces). If the distance looks borderline, agree on it as a group before you hit the putt.", image: require('../../assets/cards/illustrations/standard/from-distance.png') },
  { id: "standard-clean-card", name: "Clean Card", pack: "standard", kind: "individual", multiWinner: false, challenge: "No penalty strokes", howToWin: "Finish the hole with zero penalty strokes — the extra strokes added to your score for hitting into water, losing a ball, going out of bounds, or declaring your ball unplayable. Any penalty at all loses the card.", image: require('../../assets/cards/illustrations/standard/clean-card.png') },
  { id: "standard-pure-contact", name: "Pure Contact", pack: "standard", kind: "individual", multiWinner: false, challenge: "No tops, shanks, or whiffs", howToWin: "Hit the ball cleanly on every swing — no balls skittering along the ground off the top of the club, no shots shooting sideways off the club's neck, no complete misses. The group is the judge on anything ugly-but-debatable.", image: require('../../assets/cards/illustrations/standard/pure-contact.png') },
  { id: "standard-money-from-five", name: "Money from Five", pack: "standard", kind: "individual", multiWinner: false, challenge: "Make putt inside 5 feet", howToWin: "Make every putt you face from 5 feet or closer (about two paces from the hole). You must face at least one putt from that range during the hole — and sink them all. One miss from short range loses the card.", image: require('../../assets/cards/illustrations/standard/money-from-five.png') },
  { id: "standard-three-to-finish", name: "Three to Finish", pack: "standard", kind: "individual", multiWinner: false, challenge: "Once inside 50 yards, hole out in 3 or fewer", howToWin: "From the moment you hit your first shot within 50 yards of the flag, get the ball in the hole in 3 strokes or fewer. The count starts with that first close-range shot itself.", image: require('../../assets/cards/illustrations/standard/three-to-finish.png') },
  { id: "standard-ball-marriage", name: "Ball Marriage", pack: "standard", kind: "individual", multiWinner: false, challenge: "Finish the hole with the ball you teed off with", howToWin: "Finish the hole with the exact same ball you hit off the tee. Lose it, drown it, or swap it out for any reason, and the card is lost. Till the cup do you part.", image: require('../../assets/cards/illustrations/standard/ball-marriage.png') },
  { id: "standard-zen-master", name: "Zen Master", pack: "standard", kind: "individual", multiWinner: false, challenge: "Play the hole without one complaint", howToWin: "Play the entire hole without a single complaint, swear word, club slam, or visible meltdown — no matter what happens. The group is the judge, and one outburst loses the card.", image: require('../../assets/cards/illustrations/standard/zen-master.png') },
  { id: "standard-check-please", name: "Check, Please", pack: "standard", kind: "individual", multiWinner: false, challenge: "Hit a chip that checks up", howToWin: "Play a chip or pitch that clearly bites — no more than two bounces before it settles, no racing across the green. The group judges the check. One spinner wins it.", image: require('../../assets/cards/illustrations/standard/check-please.png') },
  // ---- the-tips ----
  { id: "the-tips-hole-out", name: "Hole Out", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Hole any shot from off the green", howToWin: "Knock the ball straight into the hole with any shot hit from off the green — a chip, a pitch, a sand shot, or even a full swing from the fairway. Watching it disappear from anywhere off the putting surface wins the card.", image: require('../../assets/cards/illustrations/the-tips/hole-out.png') },
  { id: "the-tips-drain-the-bomb", name: "Drain the Bomb", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Make a putt of 20+ feet", howToWin: "Sink a putt from 20 feet or longer — about seven paces. Agree on the distance as a group before the stroke if it's borderline.", image: require('../../assets/cards/illustrations/the-tips/drain-the-bomb.png') },
  { id: "the-tips-flag-rattler", name: "Flag Rattler", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Hit the flagstick from off the green", howToWin: "Hit the flagstick (the pole holding the flag) with a shot played from off the green. The ball doesn't have to go in — the sound of ball on pin is enough to win the card.", image: require('../../assets/cards/illustrations/the-tips/flag-rattler.png') },
  { id: "the-tips-birdie-hunter", name: "Birdie Hunter", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Birdie or better", howToWin: "Finish the hole at least one stroke better than par — golfers call that a birdie. Example: a 3 or better on a par 4. Par or worse loses the card.", image: require('../../assets/cards/illustrations/the-tips/birdie-hunter.png') },
  { id: "the-tips-stick-it", name: "Stick It", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Approach finishes inside 5 feet", howToWin: "Your approach shot — the one meant to reach the green — must stop within 5 feet of the hole (about two paces). Stick it that close and the card is yours, whether or not you make the putt.", image: require('../../assets/cards/illustrations/the-tips/stick-it.png') },
  { id: "the-tips-iron-will", name: "Iron Will", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Play the whole hole with one club, bogey or better", howToWin: "Choose one single club before the hole starts and play every shot with it — tee shot, approaches, and every putt — AND finish no worse than one over par. Touching a second club or scoring two over loses the card.", image: require('../../assets/cards/illustrations/the-tips/iron-will.png') },
  { id: "the-tips-darts", name: "Darts", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Green in regulation with the ball inside 15 feet", howToWin: "Reach the green with two putts to spare for par — 1st shot on a par 3, 2nd on a par 4, 3rd on a par 5 — AND have the ball stop within 15 feet of the hole (about five paces). Both parts must happen on the same shot.", image: require('../../assets/cards/illustrations/the-tips/darts.png') },
  { id: "the-tips-kick-in-bird", name: "Kick-In Bird", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Birdie with a tap-in finish", howToWin: "Score one better than par (a birdie) where your final putt is a tap-in — a putt so short it can't be missed, about 18 inches or less. You have to get the ball nearly into the hole with the previous shot, then tap it home for birdie.", image: require('../../assets/cards/illustrations/the-tips/kick-in-bird.png') },
  { id: "the-tips-snake-charmer", name: "Snake Charmer", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Make a putt of 30+ feet", howToWin: "Sink a putt from 30 feet or longer — ten big paces, all the way across the green. Agree on the distance as a group before the stroke if it's borderline.", image: require('../../assets/cards/illustrations/the-tips/snake-charmer.png') },
  { id: "the-tips-ten-foot-bird", name: "Ten-Foot Bird", pack: "the-tips", kind: "individual", multiWinner: false, challenge: "Hole a 10+ foot birdie putt", howToWin: "Sink a putt of 10 feet or longer (about three paces) that gives you a score one better than par — a long putt AND a birdie in one stroke. A long putt for par doesn't count; a short birdie putt doesn't either.", image: require('../../assets/cards/illustrations/the-tips/ten-foot-bird.png') },
  // ---- league ----
  { id: "league-work-it", name: "Work It", pack: "league", kind: "individual", multiWinner: false, challenge: "Hook or fade your drive", howToWin: "During the hole, hit one shot that clearly curves left and one that clearly curves right, both finishing in play. The group judges the shapes. Shot-making both directions wins it.", image: require('../../assets/cards/illustrations/league/work-it.png') },
  { id: "league-long-and-straight", name: "Long and Straight", pack: "league", kind: "individual", multiWinner: false, challenge: "Split the fairway past 150 yards", howToWin: "One tee shot must finish in the fairway and past the 150-yard marker (or an agreed landmark that far out). Distance and accuracy on the same swing wins the card.", image: require('../../assets/cards/illustrations/league/long-and-straight.png') },
  { id: "league-full-flight", name: "Full Flight", pack: "league", kind: "individual", multiWinner: false, challenge: "Carry the ball onto the green on the fly", howToWin: "Land a shot directly on the green out of the air — the ball's first bounce must be on the putting surface itself. A ball that bounces or rolls onto the green from in front doesn't count.", image: require('../../assets/cards/illustrations/league/full-flight.png') },
  { id: "league-one-and-done", name: "One and Done", pack: "league", kind: "individual", multiWinner: false, challenge: "One-putt the hole", howToWin: "Sink your very first putt on the green — one putt for the entire hole. Shots hit from the fringe or off the green count as chips, not putts, so a chip-then-one-putt still wins.", image: require('../../assets/cards/illustrations/league/one-and-done.png') },
  { id: "league-good-look", name: "Good Look", pack: "league", kind: "individual", multiWinner: false, challenge: "Putt for birdie from inside 20 feet", howToWin: "Give yourself a real chance at a birdie (a score one better than par): your ball on the green within 20 feet of the hole with your next putt being for birdie or better. You don't have to sink it — creating the chance wins the card.", image: require('../../assets/cards/illustrations/league/good-look.png') },
  { id: "league-fifteen-feet", name: "Fifteen Feet", pack: "league", kind: "individual", multiWinner: false, challenge: "Approach finishes inside 15 feet", howToWin: "Your approach shot (the one meant to reach the green) must stop within 15 feet of the hole — about five paces. On or just off the green both count; measure or let the group judge if it's close.", image: require('../../assets/cards/illustrations/league/fifteen-feet.png') },
  { id: "league-lights-out", name: "Lights Out", pack: "league", kind: "individual", multiWinner: false, challenge: "One-putt AND par or better", howToWin: "Do two things on the same hole: sink your very first putt on the green (one putt total), AND finish the hole at par or better. Both must happen — a one-putt for a bogey doesn't count.", image: require('../../assets/cards/illustrations/league/lights-out.png') },
  { id: "league-make-par", name: "Make Par", pack: "league", kind: "individual", multiWinner: false, challenge: "Par or better", howToWin: "Finish the hole at par or better — match the number on the scorecard or beat it. Even one stroke over loses the card.", image: require('../../assets/cards/illustrations/league/make-par.png') },
  { id: "league-greenlight", name: "Greenlight", pack: "league", kind: "individual", multiWinner: false, challenge: "Green in regulation", howToWin: "Get your ball onto the green fast enough that you have two putts left to make par — that means on the green with your 1st shot on a par 3, your 2nd shot on a par 4, or your 3rd shot on a par 5. (Golfers call this a \"green in regulation.\") The fringe around the green doesn't count.", image: require('../../assets/cards/illustrations/league/greenlight.png') },
  { id: "league-snake", name: "Snake", pack: "league", kind: "individual", multiWinner: false, challenge: "Make a putt of 15+ feet", howToWin: "Sink a putt from 15 feet or longer — about five paces. Agree on the distance as a group before the stroke if it's borderline.", image: require('../../assets/cards/illustrations/league/snake.png') },
  { id: "league-inside-the-leather", name: "Inside the Leather", pack: "league", kind: "individual", multiWinner: false, challenge: "First putt finishes inside the leather", howToWin: "Your first putt on the green must either go in or stop closer to the hole than the length of your putter's grip (the leather-wrapped handle — lay the putter down to check). That's where the old golf phrase \"inside the leather\" comes from.", image: require('../../assets/cards/illustrations/league/inside-the-leather.png') },
  { id: "league-dead-weight", name: "Dead Weight", pack: "league", kind: "individual", multiWinner: false, challenge: "First putt holed or finishes inside 18 inches", howToWin: "Your first putt on the green must either drop in or stop within 18 inches of the hole — about the length of your forearm. Perfect speed is the whole game here; run it long or leave it short and the card is lost.", image: require('../../assets/cards/illustrations/league/dead-weight.png') },
  { id: "league-the-purist", name: "The Purist", pack: "league", kind: "individual", multiWinner: false, challenge: "No practice swings all hole plus par or better", howToWin: "Do two things on the same hole: take zero practice swings the entire hole — walk up and hit it, every time — AND finish at par or better. One rehearsal swing or one stroke over par loses the card.", image: require('../../assets/cards/illustrations/league/the-purist.png') },
  { id: "league-forty-and-in", name: "Forty & In", pack: "league", kind: "individual", multiWinner: false, challenge: "Once inside 40 yards, hole out in 2 or fewer", howToWin: "From the moment you hit your first shot within 40 yards of the flag, get the ball in the hole in 2 strokes or fewer — for example, a chip and one putt. The count starts with that first close-range shot itself.", image: require('../../assets/cards/illustrations/league/forty-and-in.png') },
  { id: "league-corner-pocket", name: "Corner Pocket", pack: "league", kind: "individual", multiWinner: false, challenge: "Hole a putt with visible break (group judges)", howToWin: "Sink a putt that visibly curves on its way to the hole — not a straight one. The group must agree the ball clearly bent left or right before dropping. One curving made putt wins the card.", image: require('../../assets/cards/illustrations/league/corner-pocket.png') },
  { id: "league-three-foot-circle", name: "Three foot circle", pack: "league", kind: "individual", multiWinner: false, challenge: "Your first putt is within 3-feet of the hole", howToWin: "Before hitting a putt of 10 feet or longer (about three paces), announce out loud which way it will curve on its way to the hole — then sink it. Make the putt after calling the curve and the card is yours.", image: require('../../assets/cards/illustrations/league/three-foot-circle.png') },
  { id: "league-jar-it", name: "Jar It", pack: "league", kind: "individual", multiWinner: false, challenge: "Hole out from off the green", howToWin: "Sink any shot played from off the putting surface — a chip, a pitch, a bunker blast, or a putt from the fringe. The moment one disappears into the cup, the card is yours.", image: require('../../assets/cards/illustrations/league/jar-it.png') },
  { id: "league-all-green", name: "All Green", pack: "league", kind: "individual", multiWinner: false, challenge: "Once on the green, stay on the green", howToWin: "Once you get on the green, all putts must stay on the green. Don’t let your putt leave the green.", image: require('../../assets/cards/illustrations/league/all-green.png') },
  // ---- etiquette ----
  { id: "etiquette-silent-partner", name: "Silent Partner", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Quiet and still", howToWin: "Whenever another player is over the ball, stay silent and motionless — no talking, no walking, no rummaging in the bag. Hold it together all hole and the card is yours.", image: require('../../assets/cards/illustrations/etiquette/silent-partner.png') },
  { id: "etiquette-fix-it-up", name: "Fix It Up", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Repair the course", howToWin: "Repair one ball mark on the green and replace or fill one divot you take during the hole. Leave the course a little better than you found it.", image: require('../../assets/cards/illustrations/etiquette/fix-it-up.png') },
  { id: "etiquette-nice-shot", name: "Nice Shot", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Compliment the group", howToWin: "Give a genuine 'nice shot' (or 'good putt,' 'great out') to every other player at least once during the hole. Spread it around to win.", image: require('../../assets/cards/illustrations/etiquette/nice-shot.png') },
  { id: "etiquette-search-party", name: "Search Party", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Help find a ball", howToWin: "Help a playing partner hunt for a lost ball when one goes missing. If nobody loses a ball, you win by default. Be the friend with sharp eyes.", image: require('../../assets/cards/illustrations/etiquette/search-party.png') },
  { id: "etiquette-flag-duty", name: "Flag Duty", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Tend the pin", howToWin: "Tend or pull the flagstick for a playing partner at least once this hole. A small courtesy that wins you the card.", image: require('../../assets/cards/illustrations/etiquette/flag-duty.png') },
  { id: "etiquette-rake-the-trap", name: "Rake the Trap", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Leave the bunker better than you found it", howToWin: "Any bunker you play from, rake your footprints and marks smooth before you leave. Play no bunkers and you win by default. Good etiquette pays off.", image: require('../../assets/cards/illustrations/etiquette/rake-the-trap.png') },
  { id: "etiquette-gimme-giver", name: "Gimme Giver", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Concede a putt", howToWin: "Give at least one opponent a 'gimme' this hole — concede a short putt and let them pick it up. Generosity wins this one.", image: require('../../assets/cards/illustrations/etiquette/gimme-giver.png') },
  { id: "etiquette-cool-hands", name: "Cool Hands", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "No slammed or tossed clubs", howToWin: "Get through the hole without slamming, throwing, or dropping a club in frustration — no matter how the shots go. Keep it together between shots and the card is yours.", image: require('../../assets/cards/illustrations/etiquette/cool-hands.png') },
  { id: "etiquette-respect-the-line", name: "Respect the Line", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Don’t step on putting lines", howToWin: "When on the green, walk or jump over the line of your fellow golfers.  Do not walk on the line.", image: require('../../assets/cards/illustrations/etiquette/respect-the-line.png') },
  { id: "etiquette-for-the-record", name: "For the Record", pack: "etiquette", kind: "individual", multiWinner: false, challenge: "Record your scores on the next tee box", howToWin: "When you complete a hole, don’t record your score digitally or on paper until you reach the next tee box.", image: require('../../assets/cards/illustrations/etiquette/for-the-record.png') },
  // ---- mulligans ----
  { id: "mulligans-triple-threat", name: "Triple Threat", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Triple bogey or better", howToWin: "Finish the hole no more than three strokes over par (three over is a triple bogey). Example: on a par 4, a score of 7 or better wins the card; an 8 or higher loses it.", image: require('../../assets/cards/illustrations/mulligans/triple-threat.png') },
  { id: "mulligans-chip-on", name: "Chip On", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Land a chip on the green", howToWin: "Hit one chip or pitch from around the green that finishes on the putting surface. Just one clean one anytime during the hole wins it.", image: require('../../assets/cards/illustrations/mulligans/chip-on.png') },
  { id: "mulligans-texas-wedge", name: "Texas Wedge", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Putt from the fringe onto the green", howToWin: "When you're just off the green on the fringe (the short collar of grass around it), use your putter instead of a chip and roll it onto the green. Pull off one 'Texas wedge' and the card is yours.", image: require('../../assets/cards/illustrations/mulligans/texas-wedge.png') },
  { id: "mulligans-off-the-tee-up-in-the-air", name: "Off the Tee, Up in the Air", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Get your tee shot airborne", howToWin: "Get your tee shot up into the air on this hole (on a par 3, that means a clean strike that flies). A grounder off the tee loses it — everything after the tee shot is forgiven.", image: require('../../assets/cards/illustrations/mulligans/off-the-tee-up-in-the-air.png') },
  { id: "mulligans-no-snowman", name: "No Snowman", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Score less than 8", howToWin: "Get your ball in the hole in 7 total strokes or fewer, counting every swing and every penalty. An 8 or higher loses the card.", image: require('../../assets/cards/illustrations/mulligans/no-snowman.png') },
  { id: "mulligans-six-or-better", name: "Six or Better", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Score 6 or better", howToWin: "Get your ball in the hole in 6 total strokes or fewer, counting every swing and any penalty strokes, no matter what the hole's par is.", image: require('../../assets/cards/illustrations/mulligans/six-or-better.png') },
  { id: "mulligans-seeing-double", name: "Seeing Double", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Score is double par or better", howToWin: "Your score for this hole cannot be above double par. That means your max stroke for a par 3 is 6, par 4, is 8 and par 5 is 10.", image: require('../../assets/cards/illustrations/mulligans/seeing-double.png') },
  { id: "mulligans-in-bounds", name: "In Bounds", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "No OB on this hole", howToWin: "Finish the hole without ever hitting a ball out of bounds (past the white stakes that mark the edge of the course). One ball out of bounds and the card is lost.", image: require('../../assets/cards/illustrations/mulligans/in-bounds.png') },
  { id: "mulligans-no-whiffs", name: "No Whiffs", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "No swing-and-miss", howToWin: "Make contact with the ball on every swing you intend to hit. A full swing-and-a-miss (a \"whiff\") loses the card. Practice swings are fine — they don't count.", image: require('../../assets/cards/illustrations/mulligans/no-whiffs.png') },
  { id: "mulligans-one-look", name: "One Look", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Max one practice swing per shot", howToWin: "Take no more than one practice swing before each shot, the entire hole. A second rehearsal swing before any shot loses the card. Small wiggles of the club at address don't count.", image: require('../../assets/cards/illustrations/mulligans/one-look.png') },
  { id: "mulligans-steady-eddie", name: "Steady Eddie", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Max one penalty stroke", howToWin: "Finish the hole with no more than one penalty stroke. (Penalty strokes are the extra strokes added to your score for things like hitting into water, losing a ball, or going out of bounds.) One penalty is survivable — a second loses the card.", image: require('../../assets/cards/illustrations/mulligans/steady-eddie.png') },
  { id: "mulligans-find-it", name: "Find It", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "No lost balls", howToWin: "Finish the hole without losing a single ball. You can hit it into the trees or deep grass, but every ball you hit must be found — if you have to give up on one and drop a new ball, the card is lost.", image: require('../../assets/cards/illustrations/mulligans/find-it.png') },
  { id: "mulligans-lag-it-close", name: "Lag It Close", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Two-putt or better", howToWin: "Once your ball is on the green, get it in the hole using no more than two putts. Shots hit from off the green don't count against you — only putts on the green matter. Three putts and the card is lost.", image: require('../../assets/cards/illustrations/mulligans/lag-it-close.png') },
  { id: "mulligans-charge-the-cup", name: "Charge the Cup", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Roll your first putt past the hole", howToWin: "Your very first putt on the green must either go in the hole or roll at least as far as the hole. If it stops short of the hole, the card is lost. Never leave it short!", image: require('../../assets/cards/illustrations/mulligans/charge-the-cup.png') },
  { id: "mulligans-no-gimmes", name: "No Gimmes", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Putt out", howToWin: "Putt everything into the bottom of the cup — no \"that's good, pick it up,\" no freebie tap-ins. Every ball must actually drop in the hole for the card to count.", image: require('../../assets/cards/illustrations/mulligans/no-gimmes.png') },
  { id: "mulligans-three-jacks", name: "Three-Jacks", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Three-putt or better", howToWin: "Finish the hole without ever needing four putts on the green. Three putts is forgiven — but the moment you're standing over a fourth putt, the card is lost.", image: require('../../assets/cards/illustrations/mulligans/three-jacks.png') },
  { id: "mulligans-airborne", name: "Airborne", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Every full swing gets the ball airborne", howToWin: "Every full swing you take must get the ball up into the air. A ball that scoots along the ground off a full swing loses the card. Putts, and short shots you intend to keep low, don't count against you.", image: require('../../assets/cards/illustrations/mulligans/airborne.png') },
  { id: "mulligans-collar-catch", name: "Collar Catch", pack: "mulligans", kind: "individual", multiWinner: false, challenge: "Miss the green? The fringe saves you", howToWin: "If your approach (the shot meant to reach the green) misses the putting surface, it must stop on the fringe or the short grass right around it. Hit the green outright and you win by default.", image: require('../../assets/cards/illustrations/mulligans/collar-catch.png') },
  // ---- matchups ----
  { id: "matchups-closest-to-the-pin", name: "Closest to the Pin", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "Closest to the pin in regulation", howToWin: "Whoever's ball is on the green closest to the hole — while reaching it fast enough to still have two putts left for par (1st shot on a par 3, 2nd on a par 4, 3rd on a par 5) — wins. If nobody reaches the green that fast, nobody wins the card.", image: require('../../assets/cards/illustrations/matchups/closest-to-the-pin.png') },
  { id: "matchups-sniper", name: "Sniper", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "Closest approach to the pin, any shot", howToWin: "Whoever's approach shot (the shot meant to reach the green) finishes closest to the hole wins — no matter how many strokes it took to get there or where they hit it from. Everyone gets one approach; closest ball takes the card.", image: require('../../assets/cards/illustrations/matchups/sniper.png') },
  { id: "matchups-bounty", name: "Bounty", pack: "matchups", kind: "matchup", multiWinner: true, challenge: "Beat the current card leader; everyone who does draws", howToWin: "There's a bounty on whoever holds the most cards when this is flipped (the card leader). Every player who scores lower than the leader on this hole wins the card. The leader can't win their own bounty — they can only defend.", image: require('../../assets/cards/illustrations/matchups/bounty.png') },
  { id: "matchups-shot-of-the-hole", name: "Shot of the Hole", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "Group votes best shot of the hole; can't vote for yourself", howToWin: "After everyone finishes the hole, the group votes on the single best shot anyone hit — and you can't vote for your own. Most votes wins the card; if the vote ties, revote between the tied shots.", image: require('../../assets/cards/illustrations/matchups/shot-of-the-hole.png') },
  { id: "matchups-nuke-it", name: "Nuke It", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "Longest drive", howToWin: "After every player has hit exactly two shots, whoever's ball sits nearest the hole wins the card. Holing out in two beats everything. Balls out of play don't count.", image: require('../../assets/cards/illustrations/matchups/nuke-it.png') },
  { id: "matchups-putter-master", name: "Putter Master", pack: "matchups", kind: "matchup", multiWinner: true, challenge: "Fewest putts on the hole", howToWin: "Whoever uses the fewest putts on the green wins the card. Only strokes taken on the putting surface count as putts — chips from off the green don't. Ties share the win.", image: require('../../assets/cards/illustrations/matchups/putter-master.png') },
  { id: "matchups-not-the-goat", name: "Not the Goat", pack: "matchups", kind: "matchup", multiWinner: true, challenge: "Don't post the group's worst score", howToWin: "Don't post the worst score in the group. Everyone except the player (or players, if tied) with the highest score on the hole wins the card.", image: require('../../assets/cards/illustrations/matchups/not-the-goat.png') },
  { id: "matchups-longest-made", name: "Longest Made", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "Longest holed putt wins", howToWin: "Whoever sinks the longest putt on the hole wins the card. Compare the distances of every made putt — longest one takes it. If nobody makes a putt outside tap-in range, nobody wins.", image: require('../../assets/cards/illustrations/matchups/longest-made.png') },
  { id: "matchups-first-to-the-dance", name: "First to the Dance", pack: "matchups", kind: "matchup", multiWinner: false, challenge: "On the green in fewest strokes", howToWin: "Whoever gets their ball onto the green (the putting surface — golfers call it \"the dance floor\") in the fewest strokes wins the card. Ties share the win.", image: require('../../assets/cards/illustrations/matchups/first-to-the-dance.png') },
  { id: "matchups-low-score", name: "Low Score", pack: "matchups", kind: "matchup", multiWinner: true, challenge: "Lowest score on the hole wins", howToWin: "Simple: lowest total score on the hole wins the card. If two or more players tie for the lowest score, all tied players win.", image: require('../../assets/cards/illustrations/matchups/low-score.png') },
];
